import collections
import collections.abc
import re

import matplotlib.pyplot as plt
import pandas as pd

# Constants
WORDS = ['the', 'be', 'to', 'of', 'and', 'a', 'in', 'that', 'have', 'I']


def task_func(sentences_dict, word_keys):
    def _iter_sentences(obj):
        if obj is None:
            return
        if isinstance(obj, str):
            yield obj
            return
        if isinstance(obj, bytes):
            try:
                yield obj.decode("utf-8", errors="ignore")
            except Exception:
                return
            return
        if isinstance(obj, collections.abc.Mapping):
            for value in obj.values():
                yield from _iter_sentences(value)
            return
        if isinstance(obj, collections.abc.Iterable):
            for item in obj:
                yield from _iter_sentences(item)
            return

    sentences = list(_iter_sentences(sentences_dict))

    tokens = []
    for sentence in sentences:
        tokens.extend(re.findall(r"[A-Za-z]+", sentence.lower()))

    counter = collections.Counter(tokens)

    if word_keys is None:
        keys = WORDS
    elif isinstance(word_keys, str):
        keys = [word_keys]
    else:
        keys = list(word_keys)

    labels = [str(key) for key in keys]
    counts = [counter.get(str(key).lower(), 0) for key in keys]

    fig, ax = plt.subplots()
    ax.bar(labels, counts)
    ax.set_xlabel("Words")
    ax.set_ylabel("Frequency")
    ax.set_title("Word Frequencies")

    if labels:
        plt.setp(ax.get_xticklabels(), rotation=45, ha="right")

    fig.tight_layout()
    return ax
